    private val en = entries.associate { it.key to it.en }
    private val ru = entries.associate { it.key to it.ru }
    private val pl = entries.associate { it.key to it.pl }
    private val es = entries.associate { it.key to it.es }

    fun tr(language: AppLanguage, key: String): String =
        mapFor(language)[key] ?: en[key] ?: key

    fun keys(): Set<String> = en.keys

    fun translations(language: AppLanguage): Map<String, String> = mapFor(language)

    fun missingKeys(language: AppLanguage): Set<String> =
        keys() - mapFor(language).keys

    private fun mapFor(language: AppLanguage): Map<String, String> =
        when (language) {
            AppLanguage.EN -> en
            AppLanguage.RU -> ru
            AppLanguage.PL -> pl
            AppLanguage.ES -> es
        }
}
